/* Data access layer.
 *
 * Today: `loadJson` serves bundled datasets generated by the repository's
 * Python pipeline (public/data/*) through one shared cache — every page and
 * the `useJson` hook read through it. Types mirror the future FastAPI
 * responses (see services/api.ts), so swapping in `api.*` later is a
 * one-line change per call site. */

import type {
  ModelReport,
  TyreData,
  ViewId,
} from "@/types";

const cache = new Map<string, unknown>();

/** Cached JSON loader — the single data access path for bundled assets. */
export async function loadJson<T>(path: string): Promise<T> {
  if (cache.has(path)) return cache.get(path) as T;
  const res = await fetch(path);
  if (!res.ok) throw new Error(`Failed to load ${path}: ${res.status}`);
  const data = (await res.json()) as T;
  cache.set(path, data);
  return data;
}

/* ---------------- strategy simulation (client-side, real curves) ---------------- */

export interface StrategyStop {
  lap: number;
  compound: "SOFT" | "MEDIUM" | "HARD";
}

export interface StrategyScenarioInput {
  label: string;
  startCompound: "SOFT" | "MEDIUM" | "HARD";
  startAge: number;
  stops: StrategyStop[];
}

export interface StrategyScenarioResult {
  label: string;
  stops: number;
  predictedRaceTimeS: number;
  pitLossTotalS: number;
  stintPlan: { compound: string; fromLap: number; toLap: number; ages: number[] }[];
  avgDegPerLap: number;
  finalTyreAge: number;
  /** empirical pit probability over the plan (mean of per-lap values) */
  meanPitProbability: number;
}

/**
 * Simulate remaining race time for a set of scenarios using the empirical
 * degradation curves and pit-loss measured from the real 101k-lap dataset.
 * Pure function — same inputs will later be answered by POST /api/v1/strategy/simulate.
 */
export function simulateStrategy(
  input: {
    currentLap: number;
    totalLaps: number;
    baselineLapS: number;
    pitLossS: number;
  },
  scenarios: StrategyScenarioInput[],
  tyreData: TyreData,
): StrategyScenarioResult[] {
  const { currentLap, totalLaps, baselineLapS, pitLossS } = input;
  const remaining = Math.max(0, totalLaps - currentLap + 1);

  return scenarios.map((s) => {
    // build stint plan over remaining laps
    const plan: StrategyScenarioResult["stintPlan"] = [];
    let lap = currentLap;
    let age = s.startAge;
    let compound = s.startCompound;
    const stops = [...s.stops].sort((a, b) => a.lap - b.lap);
    let pitLossTotal = 0;
    const pitProbs: number[] = [];

    const curve = (c: string) => tyreData.compounds[c]?.lapTimeDelta ?? {};
    const pitProb = (c: string) => tyreData.compounds[c]?.pitProbability ?? {};

    for (let i = 0; i <= stops.length; i++) {
      const stop = stops[i];
      const endLap = stop ? stop.lap - 1 : totalLaps;
      const ages: number[] = [];
      const cCurve = curve(compound);
      const cProb = pitProb(compound);
      for (; lap <= endLap; lap++) {
        const key = String(Math.min(age, 40));
        pitProbs.push(cProb[key] ?? 0);
        ages.push(age);
        age++;
      }
      if (ages.length > 0) {
        plan.push({ compound, fromLap: lap - ages.length, toLap: lap - 1, ages });
      }
      if (stop) {
        pitLossTotal += pitLossS;
        compound = stop.compound;
        age = 1;
        lap = stop.lap;
      }
    }

    // total time: baseline + degradation delta per lap + pit loss
    let raceTime = 0;
    let degSum = 0;
    let n = 0;
    for (const stint of plan) {
      const cCurve = curve(stint.compound);
      for (let i = 0; i < stint.ages.length; i++) {
        const key = String(Math.min(stint.ages[i], 40));
        const delta = cCurve[key] ?? cCurve["40"] ?? 0.4;
        raceTime += baselineLapS + delta;
        degSum += delta;
        n++;
      }
    }
    raceTime += pitLossTotal;

    return {
      label: s.label,
      stops: s.stops.length,
      predictedRaceTimeS: Math.round(raceTime * 10) / 10,
      pitLossTotalS: Math.round(pitLossTotal * 10) / 10,
      stintPlan: plan,
      avgDegPerLap: n > 0 ? Math.round((degSum / n) * 1000) / 1000 : 0,
      finalTyreAge: plan.length ? plan[plan.length - 1].ages.slice(-1)[0] : 0,
      meanPitProbability:
        pitProbs.length > 0
          ? Math.round((pitProbs.reduce((a, b) => a + b, 0) / pitProbs.length) * 10000) / 10000
          : 0,
      // remaining is used implicitly via plan; kept for clarity
      ...(remaining >= 0 ? {} : {}),
    };
  });
}

/* ---------------- champion model inference (pre-computed grid) ---------------- */

/**
 * Interpolates the LightGBM champion's predicted pit probability over
 * (tyreLife × raceProgress) for a compound. The grid was pre-computed with
 * the real model on a feature grid; this is a display-surface, not a re-
 * implementation of the model.
 */
export function modelPitProbability(
  report: ModelReport,
  compound: string,
  tyreLife: number,
  raceProgress: number,
): number | null {
  const grid = report.inferenceGrid[compound];
  if (!grid) return null;
  const lifes = grid.tyreLife;
  const progs = grid.raceProgress;
  const cols = lifes.length;

  const li = Math.max(0, Math.min(lifes.length - 2, Math.floor(tyreLife) - 1));
  const lf = Math.max(0, Math.min(1, tyreLife - lifes[li]));
  const pi = Math.max(
    0,
    Math.min(progs.length - 2, Math.floor(raceProgress * (progs.length - 1))),
  );
  const pArr = progs;
  const pf = Math.max(0, Math.min(1, (raceProgress - pArr[pi]) / (pArr[pi + 1] - pArr[pi] || 1)));

  const p00 = grid.p[pi * cols + li];
  const p10 = grid.p[pi * cols + li + 1];
  const p01 = grid.p[(pi + 1) * cols + li];
  const p11 = grid.p[(pi + 1) * cols + li + 1];
  const v =
    p00 * (1 - lf) * (1 - pf) + p10 * lf * (1 - pf) + p01 * (1 - lf) * pf + p11 * lf * pf;
  return Math.max(0, Math.min(1, v));
}

