/* ---------------- misc helpers ---------------- */

export function formatLapTime(seconds: number): string {
  if (!seconds || seconds <= 0) return "—";
  const m = Math.floor(seconds / 60);
  const s = seconds - m * 60;
  return `${m}:${s.toFixed(3).padStart(6, "0")}`;
}

export function formatGap(seconds: number): string {
  const sign = seconds >= 0 ? "+" : "−";
  return `${sign}${Math.abs(seconds).toFixed(3)}`;
}

export function driverColor(code: string, team: string | null, index: number): string {
  if (team && team in TEAM_COLORS_SAFE) return (TEAM_COLORS_SAFE as Record<string, string>)[team];
  // deterministic fallback
  let h = 0;
  for (const ch of code) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return PALETTE[h % PALETTE.length];
}

const TEAM_COLORS_SAFE: Record<string, string> = {
  "Red Bull Racing": "#3671C6",
  Ferrari: "#E8002D",
  Mercedes: "#27F4D2",
  McLaren: "#FF8000",
  Alpine: "#FF87BC",
  "Alfa Romeo": "#C92D4B",
  "Aston Martin": "#229971",
  Haas: "#B6BABD",
  Williams: "#64C4FF",
};

const PALETTE = [
  "#E10600", "#3671C6", "#FF8000", "#27F4D2", "#FF87BC",
  "#229971", "#B6BABD", "#64C4FF", "#FFB800", "#C92D4B",
  "#43C000", "#9D4EDD", "#F77F00", "#00B4D8", "#DE3163",
  "#7F8C8D", "#D4AC0D", "#1ABC9C", "#A569BD", "#E74C3C",
];
